/* checks manifest file i (sha1 NULL = by size only): 1 when it is the copy of any supported
 * release, 0 if none. Adds 1 to fit[r] for every release r whose copy it is, so the release a whole
 * copy came from = the r with the highest fit[r] (datafile_best). A release's copy = its
 * k_datafiles_alt entry, or the English file when it has none; an entry with an empty SHA-1 = the
 * release has no such file. */
static int datafile_tally(int i, unsigned long long size, const char *sha1, int *fit) {
    int any = 0;
    for (int r = 0; r < DATAFILES_RELEASES; r++) {
        unsigned sz = k_datafiles[i].size;
        const char *h = k_datafiles[i].sha1;
        for (int k = 0; k < DATAFILES_ALT; k++)
            if (k_datafiles_alt[k].file == i && k_datafiles_alt[k].release == r) {
                sz = k_datafiles_alt[k].size;
                h = k_datafiles_alt[k].sha1;
            }
        if (*h && size == sz && (!sha1 || !strcmp(sha1, h))) {
            any = 1;
            if (fit)
                fit[r]++;
        }
    }
    return any;
}
/* manifest file i is missing: 1 when a supported release has no such file either (adds 1 to fit[r]
 * for each), 0 if all have it */
static int datafile_absent(int i, int *fit) {
    int any = 0;
    for (int k = 0; k < DATAFILES_ALT; k++)
        if (k_datafiles_alt[k].file == i && !*k_datafiles_alt[k].sha1) {
            any = 1;
            if (fit)
                fit[k_datafiles_alt[k].release]++;
        }
    return any;
}
static int datafile_best(const int *fit) {
    int b = 0;
    for (int r = 1; r < DATAFILES_RELEASES; r++)
        if (fit[r] > fit[b])
            b = r;
    return b;
}
